//! What the proxy will forward to marimo: an allow-list, by table lookup.
//!
//! S0 inventoried marimo 0.25.0's 107 routes and blocked 22 prefixes by deny-list. A
//! deny-list is fragile — every marimo upgrade can add a route — so this is the other
//! way round: `route_inventory.json` names every route and the surface that may reach
//! it, and ANYTHING THE TABLE DOES NOT NAME IS DENIED. A new marimo route can therefore
//! only stop working until someone classifies it; it cannot become reachable by default.
//!
//! The file is generated by `apps-image/tools/gen_route_inventory.py` from marimo's live
//! routes and verified against them by `apps-image/tests/test_route_inventory.py`.
//! `surface` is `both`, `edit`, `run` or `deny`; the edit surface may also use `run`
//! routes (the editor runs apps), the run surface may not use `edit` ones. marimo's own
//! `@requires("edit")` refuses edit routes in run mode as well — this is the second lock.

use std::sync::OnceLock;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Surface {
    Edit,
    Run,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Verdict {
    Allow,
    /// A frontend-bundle file: only ever a `GET`, never under an API-looking prefix.
    AllowStatic,
    Deny,
}

#[derive(serde::Deserialize)]
struct Entry {
    method: String,
    path: String,
    surface: String,
}

const INVENTORY_JSON: &str = include_str!("route_inventory.json");
/// marimo's `GET /{path:path}`: the static catch-all. Handled last and only for paths that
/// do not look like an endpoint.
const CATCH_ALL: &str = "/{path:path}";
/// A path starting with one of these is an endpoint (or a would-be one). If it matches no
/// inventory entry it is DENIED — it never falls through to the static catch-all.
const ENDPOINT_PREFIXES: [&str; 9] = [
    "/api",
    "/auth",
    "/og",
    "/terminal",
    "/ws",
    "/sse",
    "/public",
    "/@file",
    "/health",
];

fn inventory() -> &'static [Entry] {
    static CELL: OnceLock<Vec<Entry>> = OnceLock::new();
    CELL.get_or_init(|| {
        serde_json::from_str(INVENTORY_JSON).expect("route_inventory.json is valid JSON")
    })
}

/// A template segment `{name}` matches one segment; `{name:path}` matches the rest.
/// Returns the number of literal segments on a match (more = more specific).
fn matches(template: &str, path: &str) -> Option<usize> {
    let t: Vec<&str> = template.split('/').collect();
    let p: Vec<&str> = path.split('/').collect();
    let mut literals = 0;
    for (i, seg) in t.iter().enumerate() {
        if seg.starts_with('{') && seg.ends_with("path}") {
            return (p.len() > i && !p[i..].iter().all(|s| s.is_empty())).then_some(literals);
        }
        if seg.starts_with('{') {
            if p.get(i).is_none_or(|s| s.is_empty()) {
                return None;
            }
        } else {
            if p.get(i) != Some(seg) {
                return None;
            }
            literals += 1;
        }
    }
    (t.len() == p.len()).then_some(literals)
}

fn surface_allows(entry_surface: &str, wanted: Surface) -> bool {
    match (entry_surface, wanted) {
        ("both", _) => true,
        ("run", _) => true,
        ("edit", Surface::Edit) => true,
        _ => false,
    }
}

/// `method` is the HTTP method, or `WEBSOCKET` for an upgrade. `rel` is the percent-decoded,
/// lower-cased path from [`super::pathguard::check_raw_path`] with the `/e/{pod}` or
/// `/r/{version}` prefix removed (so it starts with `/`).
pub fn classify(surface: Surface, method: &str, rel: &str) -> Verdict {
    let method = match method.to_ascii_uppercase().as_str() {
        "HEAD" => "GET".to_string(),
        m => m.to_string(),
    };
    let best = inventory()
        .iter()
        .filter(|e| e.path != CATCH_ALL && e.method == method)
        .filter_map(|e| matches(&e.path.to_ascii_lowercase(), rel).map(|n| (n, e)))
        .max_by_key(|(n, _)| *n);
    if let Some((_, e)) = best {
        return if surface_allows(&e.surface, surface) {
            Verdict::Allow
        } else {
            Verdict::Deny
        };
    }
    if ENDPOINT_PREFIXES.iter().any(|p| rel.starts_with(p)) {
        return Verdict::Deny;
    }
    if method == "GET" && inventory().iter().any(|e| e.path == CATCH_ALL) {
        return Verdict::AllowStatic;
    }
    Verdict::Deny
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A concrete request path for a route template.
    fn concrete(template: &str) -> String {
        template
            .split('/')
            .map(|s| {
                if s.starts_with('{') && s.ends_with("path}") {
                    "a/b"
                } else if s.starts_with('{') {
                    "x"
                } else {
                    s
                }
            })
            .collect::<Vec<_>>()
            .join("/")
    }

    #[test]
    fn every_inventory_route_gets_exactly_the_verdict_it_was_classified_with() {
        let mut seen = 0;
        for e in inventory() {
            let path = concrete(&e.path);
            for (surface, name) in [(Surface::Edit, "edit"), (Surface::Run, "run")] {
                let want_allow = surface_allows(&e.surface, surface);
                let got = classify(surface, &e.method, &path);
                if e.path == CATCH_ALL {
                    // the catch-all is for static files only: an arbitrary `a/b` is one
                    assert_eq!(got, Verdict::AllowStatic, "{name} {} {path}", e.method);
                } else if e.path == "/assets" {
                    // WEBSOCKET /assets is marimo's static mount, listed that way only
                    // because it has no method list; nothing upgrades to it.
                    assert!(matches!(got, Verdict::Allow | Verdict::Deny));
                } else {
                    assert_eq!(
                        got,
                        if want_allow {
                            Verdict::Allow
                        } else {
                            Verdict::Deny
                        },
                        "{name} {} {path} ({})",
                        e.method,
                        e.surface
                    );
                }
                seen += 1;
            }
        }
        assert_eq!(seen, 107 * 2, "marimo 0.25.0 has 107 routes");
    }

    #[test]
    fn an_unknown_route_is_denied_so_an_upgrade_cannot_widen_what_is_reachable() {
        for rel in [
            "/api/brand/new",
            "/api/kernel/brand_new",
            "/ws2",
            "/terminal",
            "/authx",
        ] {
            for m in ["GET", "POST", "WEBSOCKET"] {
                assert_eq!(classify(Surface::Edit, m, rel), Verdict::Deny, "{m} {rel}");
            }
        }
        // a route marimo does have, with a method it does not
        assert_eq!(
            classify(Surface::Edit, "DELETE", "/api/kernel/save"),
            Verdict::Deny
        );
        assert_eq!(
            classify(Surface::Edit, "GET", "/api/kernel/save"),
            Verdict::Deny
        );
    }

    #[test]
    fn the_twenty_two_prefixes_of_spec_6_2_are_denied_everywhere_by_every_method() {
        let prefixes = [
            "/terminal",
            "/api/packages",
            "/api/secrets",
            "/api/files",
            "/api/ai",
            "/api/storage",
            "/api/home",
            "/api/kernel/copy",
            "/api/kernel/rename",
            "/api/kernel/install_missing_packages",
            "/api/kernel/save_user_config",
            "/api/export/auto_export",
            "/api/export/requirements",
            "/api/lsp",
            "/api/datasources",
            "/api/cache",
            "/api/environment",
            "/api/usage",
            "/api/sessions",
            "/api/status",
            "/auth",
            "/og",
        ];
        assert_eq!(prefixes.len(), 22);
        for p in prefixes {
            for rel in [p.to_string(), format!("{p}/anything"), format!("{p}/list")] {
                for s in [Surface::Edit, Surface::Run] {
                    for m in ["GET", "POST", "PUT", "DELETE", "WEBSOCKET"] {
                        assert_eq!(classify(s, m, &rel), Verdict::Deny, "{s:?} {m} {rel}");
                    }
                }
            }
        }
    }

    #[test]
    fn the_static_catch_all_serves_bundle_files_to_get_and_nothing_else() {
        assert_eq!(
            classify(Surface::Edit, "GET", "/assets/index-abc.js"),
            Verdict::AllowStatic
        );
        assert_eq!(
            classify(Surface::Run, "GET", "/assets/font.woff2"),
            Verdict::AllowStatic
        );
        assert_eq!(
            classify(Surface::Run, "HEAD", "/favicon.ico"),
            Verdict::AllowStatic
        );
        assert_eq!(
            classify(Surface::Edit, "POST", "/assets/index-abc.js"),
            Verdict::Deny
        );
        assert_eq!(classify(Surface::Edit, "PUT", "/anything"), Verdict::Deny);
    }

    #[test]
    fn the_run_surface_cannot_reach_edit_only_routes() {
        for rel in [
            "/api/kernel/save",
            "/api/kernel/run",
            "/api/kernel/execute",
            "/api/export/script",
            "/api/document/transaction",
        ] {
            assert_eq!(
                classify(Surface::Run, "POST", rel),
                Verdict::Deny,
                "run {rel}"
            );
            assert_eq!(
                classify(Surface::Edit, "POST", rel),
                Verdict::Allow,
                "edit {rel}"
            );
        }
        // what a running app needs is open to both
        assert_eq!(
            classify(Surface::Run, "POST", "/api/kernel/set_ui_element_value"),
            Verdict::Allow
        );
        assert_eq!(classify(Surface::Run, "WEBSOCKET", "/ws"), Verdict::Allow);
        assert_eq!(
            classify(Surface::Run, "WEBSOCKET", "/ws_sync"),
            Verdict::Deny
        );
        assert_eq!(
            classify(Surface::Edit, "WEBSOCKET", "/ws_sync"),
            Verdict::Allow
        );
    }

    #[test]
    fn dynamic_segments_match_by_shape_and_the_most_specific_route_wins() {
        assert_eq!(
            classify(Surface::Run, "GET", "/@file/12-a.png"),
            Verdict::Allow
        );
        assert_eq!(
            classify(Surface::Run, "GET", "/public/img/a.png"),
            Verdict::Allow
        );
        assert_eq!(
            classify(Surface::Run, "GET", "/public"),
            Verdict::Deny,
            "no file named"
        );
        assert_eq!(classify(Surface::Edit, "GET", "/"), Verdict::Allow);
        assert_eq!(classify(Surface::Edit, "GET", "/healthz"), Verdict::Allow);
        assert_eq!(
            classify(Surface::Edit, "GET", "/health/extra"),
            Verdict::Deny
        );
    }
}
